        when(e2.getSequencia()).thenReturn(2);
        when(e2.getCpf()).thenReturn("22222222222");
        when(e2.getCnpj()).thenReturn(null);
        when(e2.getDataEvento()).thenReturn(LocalDateTime.of(2020, 1, 2, 11, 0));
        when(e2.getMotivo()).thenReturn("Motivo 2");

        listaCCe.add(e1);
        listaCCe.add(e2);

        ConfiguracoesNfe configuracao = mock(ConfiguracoesNfe.class);
        Estado estado = mock(Estado.class);
        Ambiente ambiente = mock(Ambiente.class);
        ZoneId zoneId = ZoneId.systemDefault();

        when(configuracao.getEstado()).thenReturn(estado);
        when(estado.getCodigoUF()).thenReturn("33");
        when(configuracao.getAmbiente()).thenReturn(ambiente);
        when(ambiente.getCodigo()).thenReturn("1");
        when(configuracao.getZoneId()).thenReturn(zoneId);

        Object result = CartaCorrecaoUtil.montaCCe(listaCCe, configuracao);

        assertNotNull(result);
        Class<?> cls = result.getClass();

        // Versao
        Object versao = cls.getMethod("getVersao").invoke(result);
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CCE, versao);

        // IdLote
        Object idLote = cls.getMethod("getIdLote").invoke(result);
        assertEquals("1", idLote);

        // Eventos list
        Object eventosObj = cls.getMethod("getEvento").invoke(result);
        assertTrue(eventosObj instanceof List);
        List<?> eventos = (List<?>) eventosObj;
        assertEquals(2, eventos.size());

        for (int i = 0; i < 2; i++) {
            Object tEvento = eventos.get(i);
            // InfEvento
            Object infEvento = tEvento.getClass().getMethod("getInfEvento").invoke(tEvento);

            // Id
            String chave = i == 0 ? e1.getChave() : e2.getChave();
            Object id = infEvento.getClass().getMethod("getId").invoke(infEvento);
            String expectedId = "ID" + EventosEnum.CCE.getCodigo() + chave + ChaveUtil.completarComZerosAEsquerda(String.valueOf(i + 1), 2);
            assertEquals(expectedId, id);

            // ChNFe
            Object chNFe = infEvento.getClass().getMethod("getChNFe").invoke(infEvento);
            assertEquals(chave, chNFe);

            // CPF
            Object cpf = infEvento.getClass().getMethod("getCPF").invoke(infEvento);
            String expectedCpf = i == 0 ? (String) e1.getClass().getMethod("getCpf").invoke(e1) : (String) e2.getClass().getMethod("getCpf").invoke(e2);
            assertEquals(expectedCpf, cpf);

            // CNPJ
            Object cnpj = infEvento.getClass().getMethod("getCNPJ").invoke(infEvento);
            assertNull(cnpj);

            // TpEvento
            Object tpEvento = infEvento.getClass().getMethod("getTpEvento").invoke(infEvento);
            assertEquals(EventosEnum.CCE.getCodigo(), tpEvento);

            // NSeqEvento
            Object nSeqEvento = infEvento.getClass().getMethod("getNSeqEvento").invoke(infEvento);
            assertEquals(String.valueOf(i + 1), nSeqEvento);

            // DetEvento
            Object detEvento = infEvento.getClass().getMethod("getDetEvento").invoke(infEvento);
            Object descEvento = detEvento.getClass().getMethod("getDescEvento").invoke(detEvento);
            Object xCorrecao = detEvento.getClass().getMethod("getXCorrecao").invoke(detEvento);

            assertEquals("Carta de Correção", descEvento);
            String motivo = i == 0 ? "Motivo 1" : "Motivo 2";
            assertEquals(motivo, xCorrecao);
        }
    }
}

